const int kNumAxes = 3;
const int kNumBins = 16;

T bestCost = std::numeric_limits<T>::max();
int bestAxis = -1;
T bestPos = T(0);

real3<T> extent = bmax - bmin;
T parentArea = T(2) * (extent[0] * extent[1] + extent[1] * extent[2] + extent[2] * extent[0]);
int totalPrims = bins->count;

if (totalPrims <= 1) {
    return false;
}

for (int axis = 0; axis < kNumAxes; ++axis) {
    if (extent[axis] < std::numeric_limits<T>::epsilon()) {
        continue;
    }

    T binWidth = extent[axis] / T(kNumBins);
    if (binWidth <= T(0)) {
        continue;
    }

    struct BinInfo {
        real3<T> bmin;
        real3<T> bmax;
        int count;
    };
    std::vector<BinInfo> binInfo(kNumBins);
    for (int i = 0; i < kNumBins; ++i) {
        binInfo[i].bmin = real3<T>(std::numeric_limits<T>::max());
        binInfo[i].bmax = real3<T>(-std::numeric_limits<T>::max());
        binInfo[i].count = 0;
    }

    for (int i = 0; i < totalPrims; ++i) {
        real3<T> primBmin, primBmax;
        bins->get_bounds(&primBmin, &primBmax, i);
        T center = (primBmin[axis] + primBmax[axis]) * T(0.5);
        int binIndex = int((center - bmin[axis]) / binWidth);
        binIndex = std::max(0, std::min(kNumBins - 1, binIndex));

        binInfo[binIndex].bmin = real3<T>(
            std::min(binInfo[binIndex].bmin[0], primBmin[0]),
            std::min(binInfo[binIndex].bmin[1], primBmin[1]),
            std::min(binInfo[binIndex].bmin[2], primBmin[2]));
        binInfo[binIndex].bmax = real3<T>(
            std::max(binInfo[binIndex].bmax[0], primBmax[0]),
            std::max(binInfo[binIndex].bmax[1], primBmax[1]),
            std::max(binInfo[binIndex].bmax[2], primBmax[2]));
        binInfo[binIndex].count++;
    }

    std::vector<BinInfo> left(kNumBins);
    std::vector<BinInfo> right(kNumBins);

    left[0] = binInfo[0];
    for (int i = 1; i < kNumBins; ++i) {
        left[i].bmin = real3<T>(
            std::min(left[i-1].bmin[0], binInfo[i].bmin[0]),
            std::min(left[i-1].bmin[1], binInfo[i].bmin[1]),
            std::min(left[i-1].bmin[2], binInfo[i].bmin[2]));
        left[i].bmax = real3<T>(
            std::max(left[i-1].bmax[0], binInfo[i].bmax[0]),
            std::max(left[i-1].bmax[1], binInfo[i].bmax[1]),
            std::max(left[i-1].bmax[2], binInfo[i].bmax[2]));
        left[i].count = left[i-1].count + binInfo[i].count;
    }

    right[kNumBins-1] = binInfo[kNumBins-1];
    for (int i = kNumBins-2; i >= 0; --i) {
        right[i].bmin = real3<T>(
            std::min(right[i+1].bmin[0], binInfo[i].bmin[0]),
            std::min(right[i+1].bmin[1], binInfo[i].bmin[1]),
            std::min(right[i+1].bmin[2], binInfo[i].bmin[2]));
        right[i].bmax = real3<T>(
            std::max(right[i+1].bmax[0], binInfo[i].bmax[0]),
            std::max(right[i+1].bmax[1], binInfo[i].bmax[1]),
            std::max(right[i+1].bmax[2], binInfo[i].bmax[2]));
        right[i].count = right[i+1].count + binInfo[i].count;
    }

    for (int i = 0; i < kNumBins - 1; ++i) {
        int leftCount = left[i].count;
        int rightCount = right[i+1].count;
        if (leftCount == 0 || rightCount == 0) {
            continue;
        }

        real3<T> leftExtent = left[i].bmax - left[i].bmin;
        T leftArea = T(2) * (leftExtent[0] * leftExtent[1] + leftExtent[1] * leftExtent[2] + leftExtent[2] * leftExtent[0]);
        real3<T> rightExtent = right[i+1].bmax - right[i+1].bmin;
        T rightArea = T(2) * (rightExtent[0] * rightExtent[1] + rightExtent[1] * rightExtent[2] + rightExtent[2] * rightExtent[0]);

        T cost = T(0.125) + (leftArea * leftCount + rightArea * rightCount) / parentArea;
        if (cost < bestCost) {
            bestCost = cost;
            bestAxis = axis;
            bestPos = bmin[axis] + (i + 1) * binWidth;
        }
    }
}

if (bestAxis < 0) {
    return false;
}

cut_pos[0] = (bestAxis == 0) ? bestPos : T(0);
cut_pos[1] = (bestAxis == 1) ? bestPos : T(0);
cut_pos[2] = (bestAxis == 2) ? bestPos : T(0);
*minCostAxis = bestAxis;

return true;

